-- ============================================================
-- 0077: Inventory Schema Hardening — Phase 1
-- ============================================================
-- 1. is_stale column on inventory_balances
-- 2. Trigger: mark snapshot stale on new movement
-- 3. Trigger: GL status state-machine guard (no unposting)
-- 4. Performance indexes
-- 5. items master seed from JSON source (4,830 items)
-- Note: movement_types table already exists from migration 0076
-- ============================================================

-- ── 1. is_stale column on inventory_balances ───────────────
ALTER TABLE inventory_balances ADD COLUMN is_stale INTEGER NOT NULL DEFAULT 0;

-- ── 2. Trigger: mark snapshot stale on every new movement ──
CREATE TRIGGER IF NOT EXISTS trg_inv_bal_mark_stale
AFTER INSERT ON inventory_movements
BEGIN
  UPDATE inventory_balances
  SET    is_stale = 1
  WHERE  company_id = NEW.company_id
    AND  item_code  = NEW.item_code
    AND  warehouse  = NEW.warehouse;
END;

-- ── 3. GL status state-machine guard ───────────────────────
CREATE TRIGGER IF NOT EXISTS trg_inv_mov_gl_status_guard
BEFORE UPDATE OF gl_posting_status ON inventory_movements
WHEN OLD.gl_posting_status = 'posted'
 AND NEW.gl_posting_status IN ('pending', 'posting', 'failed')
BEGIN
  SELECT RAISE(ABORT, 'GL_STATUS_IMMUTABLE: cannot revert a posted movement');
END;

-- ── 4. Performance indexes ─────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_inv_mov_movement_type
  ON inventory_movements(company_id, movement_type);

CREATE INDEX IF NOT EXISTS idx_inv_mov_gl_status
  ON inventory_movements(company_id, gl_posting_status);

CREATE INDEX IF NOT EXISTS idx_inv_mov_item_wh_date
  ON inventory_movements(company_id, item_code, warehouse, movement_date DESC);

CREATE INDEX IF NOT EXISTS idx_inv_bal_stale
  ON inventory_balances(company_id, is_stale);

